task_id: feature-flags-support
summary: "Implement support for configurable feature flags with admin-only access, including unit and integration tests"
depends_on: ["stage-1-core-models", "stage-2-auth"]
local_goals:
  - id: L1
    description: "Define a FeatureFlag model in Prisma schema"
    verification:
      type: file_exists
      path: "apps/api/db/schema.prisma"
      expect:
        content: |
          model FeatureFlag {
            id       String   @id @default(uuid())
            name     String   @unique
            enabled  Boolean  @default(false)
            createdAt DateTime @default(now())
            updatedAt DateTime @updatedAt
          }
  - id: L2
    description: "Create a FeatureFlags service to manage feature flags"
    verification:
      type: file_exists
      path: "apps/api/src/services/featureFlags.service.ts"
      expect:
        content: |
          import { Injectable } from '@nestjs/common';
          import { PrismaService } from '../prisma/prisma.service';

          @Injectable()
          export class FeatureFlagsService {
            constructor(private readonly prisma: PrismaService) {}

            async getFeatureFlag(name: string): Promise<FeatureFlag> {
              return this.prisma.featureFlag.findUnique({ where: { name } });
            }

            async updateFeatureFlag(name: string, enabled: boolean): Promise<FeatureFlag> {
              return this.prisma.featureFlag.update({
                where: { name },
                data: { enabled }
              });
            }
          }
  - id: L3
    description: "Create a FeatureFlags controller to expose admin endpoints"
    verification:
      type: file_exists
      path: "apps/api/src/controllers/featureFlags.controller.ts"
      expect:
        content: |
          import { Controller, Get, Patch, Body, Param } from '@nestjs/common';
          import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
          import { FeatureFlagsService } from '../services/featureFlags.service';

          @Controller('api/v1/feature-flags')
          @ApiTags('Feature Flags')
          @ApiBearerAuth()
          export class FeatureFlagsController {
            constructor(private readonly featureFlagsService: FeatureFlagsService) {}

            @Get(':name')
            @ApiOperation({ summary: 'Get a feature flag' })
            async getFeatureFlag(@Param('name') name: string): Promise<FeatureFlag> {
              return this.featureFlagsService.getFeatureFlag(name);
            }

            @Patch(':name')
            @ApiOperation({ summary: 'Update a feature flag' })
            async updateFeatureFlag(
              @Param('name') name: string,
              @Body() body: { enabled: boolean }
            ): Promise<FeatureFlag> {
              return this.featureFlagsService.updateFeatureFlag(name, body.enabled);
            }
          }
  - id: L4
    description: "Write unit tests for FeatureFlags service"
    verification:
      type: file_exists
      path: "apps/api/tests/services/featureFlags.service.spec.ts"
      expect:
        content: |
          import { Test, TestingModule } from '@nestjs/testing';
          import { PrismaService } from '../prisma/prisma.service';
          import { FeatureFlagsService } from './featureFlags.service';

          describe('FeatureFlagsService', () => {
            let service: FeatureFlagsService;
            let prismaServiceMock: Partial<PrismaService>;

            beforeEach(async () => {
              prismaServiceMock = {
                featureFlag: {
                  findUnique: jest.fn(),
                  update: jest.fn()
                }
              };

              const module: TestingModule = await Test.createTestingModule({
                providers: [
                  FeatureFlagsService,
                  { provide: PrismaService, useValue: prismaServiceMock }
                ]
              }).compile();

              service = module.get<FeatureFlagsService>(FeatureFlagsService);
            });

            it('should be defined', () => {
              expect(service).toBeDefined();
            });

            it('should get a feature flag', async () => {
              const name = 'test-feature';
              prismaServiceMock.featureFlag.findUnique.mockResolvedValue({ id: name, name, enabled: true });
              expect(await service.getFeatureFlag(name)).toEqual({ id: name, name, enabled: true });
            });

            it('should update a feature flag', async () => {
              const name = 'test-feature';
              prismaServiceMock.featureFlag.update.mockResolvedValue({ id: name, name, enabled: false });
              expect(await service.updateFeatureFlag(name, false)).toEqual({ id: name, name, enabled: false });
            });
          });
  - id: L5
    description: "Write integration tests for FeatureFlags controller"
    verification:
      type: file_exists
      path: "apps/api/tests/controllers/featureFlags.controller.spec.ts"
      expect:
        content: |
          import { Test, TestingModule } from '@nestjs/testing';
          import { INestApplication } from '@nestjs/common';
          import request from 'supertest';
          import { AppModule } from '../app.module';

          describe('FeatureFlagsController (e2e)', () => {
            let app: INestApplication;

            beforeEach(async () => {
              const moduleFixture: TestingModule = await Test.createTestingModule({
                imports: [AppModule]
              }).compile();

              app = moduleFixture.createNestApplication();
              await app.init();
            });

            it('/api/v1/feature-flags/:name (GET)', async () => {
              const name = 'test-feature';
              return request(app.getHttpServer())
                .get(`/api/v1/feature-flags/${name}`)
                .set('Authorization', `Bearer ${process.env.ADMIN_TOKEN}`)
                .expect(200)
                .expect({ id: name, name, enabled: true });
            });

            it('/api/v1/feature-flags/:name (PATCH)', async () => {
              const name = 'test-feature';
              return request(app.getHttpServer())
                .patch(`/api/v1/feature-flags/${name}`)
                .set('Authorization', `Bearer ${process.env.ADMIN_TOKEN}`)
                .send({ enabled: false })
                .expect(200)
                .expect({ id: name, name, enabled: false });
            });
          });
global_goals_refs: ["G5", "G13"]
context:
  language: TypeScript
  framework: NestJS
  orm: Prisma
  test_framework: Jest
